package com.tradepilot.backtest.engine;
import com.tradepilot.backtest.model.BacktestBar; import java.math.*; import java.time.*; import java.util.*;
/** A swing is emitted only when its right-side confirmation bars have closed. */
public class SwingDetector { public List<Swing> confirmed(List<BacktestBar> bars,int left,int right){List<Swing> out=new ArrayList<>();for(int i=left;i+right<bars.size();i++){BacktestBar c=bars.get(i);if(bars.subList(i-left,i+right+1).stream().anyMatch(b->b.instrumentId()!=c.instrumentId()))continue;boolean high=true,low=true;for(int j=i-left;j<=i+right;j++){if(j==i)continue;high&=c.high().compareTo(bars.get(j).high())>0;low&=c.low().compareTo(bars.get(j).low())<0;}if(high)out.add(new Swing(Type.HIGH,c.high(),c.time(),BarTiming.availableAt(bars.get(i+right)),c.instrumentId()));if(low)out.add(new Swing(Type.LOW,c.low(),c.time(),BarTiming.availableAt(bars.get(i+right)),c.instrumentId()));}return out;} public enum Type{HIGH,LOW} public record Swing(Type type,BigDecimal price,Instant timestamp,Instant confirmedAt,long instrumentId){} }
